const businessRow = { event_id: 'booking-8472-confirm-1', appointment_reference: 'booking-8472', phone: '+14155550100' };
return [{ json: {
  dry_run: true,
  goal_id: '',
  reviewed_goal_interface: '',
  business_event_id: businessRow.event_id,
  phone: businessRow.phone,
  variables: { test_reference: businessRow.appointment_reference },
} }];

const preparation = $input.first().json;
const settings = $('Goal Settings and Business Mapping').first().json;
if (typeof settings.dry_run !== 'boolean') throw new Error('dry_run must be a boolean.');
const live = settings.dry_run === false && preparation.ready === true;
if (live && (!/^\+[1-9]\d{7,14}$/.test(settings.phone) || /^\+14155550\d{3}$/.test(settings.phone) || !/^[A-Za-z0-9_-]{1,64}$/.test(settings.business_event_id))) throw new Error('Set an authorized E.164 phone and stable business event before live execution.');
return [{ json: { ...preparation, live } }];

const run = $input.first().json;
const prepared = $('Prepare Goal Run Configuration').first().json;
const samePublication = run.goal_id === prepared.goal_id && run.run_spec?.id === prepared.run_spec_id && run.run_spec?.version === prepared.run_spec_version;
const confirmed = samePublication && run.status === 'completed' && run.result_status === 'available' && run.result?.confirmed === 'yes';
return [{ json: { goal_run_id: run.id, run_spec: run.run_spec, result_status: run.result_status, mapping_needs_review: !samePublication, business_status: samePublication ? (confirmed ? 'confirmed' : 'unknown') : 'review_required', recovery: 'Save this Goal Run ID. Use Goal Run Get after interruption; never create a replacement run.' } }];
